public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    if (k <= 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        freq[r]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // If k is even, check remainder k/2
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }
    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // already handled k even case
            continue;
        }
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) return "";
    java.util.TreeMap<Character, Integer> map = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        map.put(c, map.getOrDefault(c, 0) + 1);
    }
    StringBuilder sb = new StringBuilder();
    while (!map.isEmpty()) {
        // Ascending pass: pick one of each distinct character in ascending order
        java.util.Iterator<java.util.Map.Entry<Character, Integer>> ascIt = map.entrySet().iterator();
        while (ascIt.hasNext()) {
            java.util.Map.Entry<Character, Integer> e = ascIt.next();
            char c = e.getKey();
            sb.append(c);
            int cnt = e.getValue() - 1;
            if (cnt == 0) {
                ascIt.remove();
            } else {
                e.setValue(cnt);
            }
        }
        // Descending pass: pick one of each distinct character in descending order
        java.util.Iterator<java.util.Map.Entry<Character, Integer>> descIt = map.descendingMap().entrySet().iterator();
        while (descIt.hasNext()) {
            java.util.Map.Entry<Character, Integer> e = descIt.next();
            char c = e.getKey();
            sb.append(c);
            int cnt = e.getValue() - 1;
            if (cnt == 0) {
                descIt.remove();
            } else {
                e.setValue(cnt);
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    // sets[i] will contain all possible sums achievable with i elements
    @SuppressWarnings("unchecked")
    Set<Integer>[] sets = new Set[n + 1];
    for (int i = 0; i <= n; i++) sets[i] = new HashSet<>();
    sets[0].add(0);
    for (int num : nums) {
        // iterate sizes in reverse to avoid using the same element twice
        for (int size = n - 1; size >= 0; size--) {
            if (sets[size].isEmpty()) continue;
            for (int sum : sets[size]) {
                sets[size + 1].add(sum + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((k * totalSum) % n != 0) continue;
        int target = (k * totalSum) / n;
        if (sets[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int curr = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

