public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (k == 0) return true;
    if (n < k) return false;
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int mask = 0;
    // Build initial mask for first k characters
    for (int i = 0; i < k; i++) {
        mask = (mask << 1) | (s.charAt(i) - '0');
    }
    seen[mask] = true;
    int count = 1;
    int maskLimit = total - 1; // (1 << k) - 1
    for (int i = k; i < n; i++) {
        mask = ((mask << 1) & maskLimit) | (s.charAt(i) - '0');
        if (!seen[mask]) {
            seen[mask] = true;
            count++;
            if (count == total) return true;
        }
    }
    return count == total;
}

