public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    long maxSum = nums[0];
    long curMax = nums[0];
    long minSum = nums[0];
    long curMin = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        curMax = Math.max(val, curMax + val);
        maxSum = Math.max(maxSum, curMax);
        curMin = Math.min(val, curMin + val);
        minSum = Math.min(minSum, curMin);
    }
    long result = Math.max(maxSum, -minSum);
    return (int) result;
}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    List<Integer> fib = new ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (true) {
        int next = fib.get(fib.size() - 1) + fib.get(fib.size() - 2);
        if (next > k) break;
        fib.add(next);
    }

    int count = 0;
    int remaining = k;
    // Greedy: subtract the largest Fibonacci number <= remaining
    for (int i = fib.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fib.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    int count = 0;
    for (int val : small) {
        count++;
        if (count == k) return val;
    }
    for (int i = large.size() - 1; i >= 0; i--) {
        count++;
        if (count == k) return large.get(i);
    }
    return -1;
}

public String makeGood(String s) {
