public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low == 0) {
        result.add(0);
    }
    Queue<Long> queue = new LinkedList<>();
    for (int d = 1; d <= 9; d++) {
        queue.add((long) d);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        int lastDigit = (int) (num % 10);
        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.add(next);
            }
        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.add(next);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) return 0;
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

